<script>
  import {
    getMatchData,
    mergeItems,
    orderItems,
  } from './autocomplete.svelte.js'
  import { getCombobox } from './combobox.svelte.js'
  import ComboboxOptions from './ComboboxOptions.svelte'
  import { getValueAndLabel, selectOptions } from './select.svelte.js'

  /**
   * @import { Snippet } from 'svelte'
   * @import { OrderBy } from './autocomplete.svelte.js'
   * @import { SelectEntry } from './select.svelte.js'
   */

  /**
   * @typedef {object} AutocompleteOptionsProps
   * @property {string} id Matches the Autocomplete's `target`
   * @property {SelectEntry[]} [items] Options to render. With `search`, what shows before results arrive. A string is both value and label.
   * @property {OrderBy} [orderBy] Key or comparator sorting `items` and results
   * @property {HTMLDivElement | null} [ref]
   * @property {string} [class]
   * @property {boolean} [inline] Render in the flow instead of a popover
   * @property {number} [size] How many options to show before scrolling
   * @property {string} [aria-label]
   * @property {string} [aria-labelledby]
   * @property {Snippet<[any]>} [option] Replaces an option's contents
   * @property {Snippet} [check] Replaces the check a selected option shows
   * @property {Snippet} [loading] Shows while `search` runs
   * @property {Snippet} [empty] Shows when `search` finds nothing
   * @property {Snippet} [failed] Shows when `search` throws
   * @property {Snippet<[string]>} [create] Replaces the create option's wording
   * @property {Snippet} [children] Options written as `<li>` elements
   */

  /** @type {AutocompleteOptionsProps & Record<string, any>} */
  let {
    ref = $bindable(null),
    id,
    items,
    orderBy,
    option,
    loading,
    empty,
    failed,
    create,
    children,
    ...rest
  } = $props()

  const combobox = $derived(getCombobox(id))
  const results = $derived(combobox?.state.results)
  const shownItems = $derived(
    items || results
      ? orderItems({ items: mergeItems({ items, results }), orderBy })
      : undefined,
  )
  const searchState = $derived(combobox?.state.searchState ?? 'idle')
  const matchCount = $derived(combobox?.state.matchCount ?? 0)
  const created = $derived(combobox?.state.created ?? [])
  const query = $derived(combobox?.state.query ?? '')

  // The input part registers these, and it can hydrate after this one
  const multiple = $derived(combobox?.options.multiple ?? false)
  const creatable = $derived(combobox?.options.creatable ?? false)
  const matchBy = $derived(combobox?.options.matchBy)

  // Text an option already says needs no create option under it
  const canCreate = $derived(
    creatable && Boolean(query) && !combobox?.state.hasExactMatch,
  )
</script>

<ComboboxOptions
  {...rest}
  {id}
  actions={[{ fn: selectOptions, props: { items: shownItems } }]}
  {multiple}
  bind:ref
>
  {#if shownItems}
    {#each shownItems as item, index (index)}
      {@const { value, label } = getValueAndLabel(item)}
      <li
        {...getMatchData({ item, matchBy })}
        id="{id}-option-{index}"
        data-index={index}
        data-label={label}
        data-position={index}
        data-value={value}
        role="option"
      >
        {#if option}{@render option(item)}{:else}{label}{/if}
      </li>
    {/each}
  {:else}
    {@render children?.()}
  {/if}

  <!-- A created value is an option like any other, from the moment it is made. `data-appended` says it renders from its own block below the list, so filtering leaves it where it is. -->
  {#each created as createdOption (createdOption.value)}
    <li
      id="{id}-created-{createdOption.value}"
      aria-selected="true"
      data-appended=""
      data-label={createdOption.label}
      data-value={createdOption.value}
      role="option"
    >
      {createdOption.label}
    </li>
  {/each}

  {#if canCreate}
    <!-- svelte-ignore a11y_role_has_required_aria_props -->
    <li
      id="{id}-create"
      class="select-create"
      data-appended=""
      data-create=""
      data-label={query}
      role="option"
    >
      {#if create}{@render create(query)}{:else}Create "{query}"{/if}
    </li>
  {/if}

  {#snippet status()}
    {#if searchState === 'searching' && loading}
      <div class="combobox-status" data-state="searching">
        {@render loading()}
      </div>
    {/if}

    {#if searchState === 'done' && !matchCount && empty}
      <div class="combobox-status" data-state="empty">{@render empty()}</div>
    {/if}

    {#if searchState === 'failed' && failed}
      <div class="combobox-status" data-state="failed">{@render failed()}</div>
    {/if}
  {/snippet}
</ComboboxOptions>
